import { List } from 'immutable';
import { isNil } from 'lodash';
import { ITEM_TYPES } from './itemTypes';

/**
 * Generates default itemScores
 * @param {int} total number of scores
 * @param {int} override optional override default value
 * @returns {Array} itemScores with score value
 */
export function generateDefaultScores(total, override = false) {
  const scores = [];

  for (let i = 0; i < total; i++) {
    // Yes/No's NO score should be 0
    const value = total === 2 ? i : i + 1;

    scores[i] = {
      resultDouble: value,
      score: override !== false ? override : value,
    };
  }

  return scores;
}

/**
 * Gets default itemScores for a specified item type
 *
 * @param {string} type ITEM_TYPES enum value
 * @param {boolean} override - Should we override the score if there is none.
 *
 * @returns {Array} itemScores with default values
 */
export function getDefaultScoresByType(type, override = false) {
  switch (type) {
    case ITEM_TYPES.YES_NO:
      return generateDefaultScores(2, override);
    case ITEM_TYPES.RATING_1_5:
      return generateDefaultScores(5, override);
    case ITEM_TYPES.RATING_1_10:
      return generateDefaultScores(10, override);
    default:
      return null;
  }
}

/**
 * Checks whether all item scores have valid score values
 * @param {Array} itemScores array of scores ({ resultDouble, score })
 * @returns {bool} all scores are populated
 */
export function checkAllScoresArePopulated(itemScores = []) {
  if (List.isList(itemScores)) {
    return (
      itemScores.size > 0 &&
      isNil(itemScores.find((score) => isNil(score.get('score'))))
    );
  }

  return (
    itemScores.length > 0 &&
    isNil(itemScores.find((score) => isNil(score.score)))
  );
}
